import hashlib
import hmac
import os
import time
import threading
from dataclasses import dataclass, field
from typing import Dict, Optional, Tuple
from collections import defaultdict


@dataclass
class TokenRecord:
    tenant_id: str
    api_key_hash: bytes
    salt: bytes
    issued_at: float  # Unix timestamp as float
    ttl: int  # seconds
    revoked: bool = False


@dataclass
class AuthResult:
    authenticated: bool
    tenant_id: Optional[str] = None
    error: Optional[str] = None


class SecureTokenStore:
    """Manages authentication tokens with expiration and revocation."""

    def __init__(self, max_clock_skew: int = 300):
        self._tokens: Dict[str, TokenRecord] = {}
        self._lock = threading.RLock()
        self._max_clock_skew = max_clock_skew
        self._rate_limits: Dict[str, list] = defaultdict(list)
        self._failed_attempts: Dict[str, int] = defaultdict(int)
        self._lockout_until: Dict[str, float] = {}

    def register_token(self, tenant_id: str, api_key: str, ttl: int = 86400) -> str:
        """Register a new API key for a tenant with TTL."""
        salt = os.urandom(32)
        key_hash = hashlib.pbkdf2_hmac(
            'sha256', api_key.encode('utf-8'), salt, 150000
        )
        token_id = os.urandom(16).hex()
        issued_at = time.time()

        with self._lock:
            self._tokens[token_id] = TokenRecord(
                tenant_id=tenant_id,
                api_key_hash=key_hash,
                salt=salt,
                issued_at=issued_at,
                ttl=ttl,
                revoked=False
            )
        return token_id

    def revoke_token(self, token_id: str) -> bool:
        with self._lock:
            if token_id in self._tokens:
                self._tokens[token_id].revoked = True
                return True
            return False

    def _is_token_expired(self, record: TokenRecord) -> bool:
        """Check if token has expired based on issued_at + ttl."""
        current_time = time.time()
        elapsed = current_time - record.issued_at

        if elapsed < -self._max_clock_skew:
            # Clock went significantly backwards - treat as expired for safety
            return True

        return elapsed > (record.ttl + self._max_clock_skew)

    def _check_rate_limit(self, source_ip: str) -> bool:
        """Returns True if request should be allowed."""
        now = time.time()

        # Check lockout
        if source_ip in self._lockout_until:
            if now < self._lockout_until[source_ip]:
                return False
            else:
                del self._lockout_until[source_ip]
                self._failed_attempts[source_ip] = 0

        # Sliding window rate limit
        window = self._rate_limits[source_ip]
        window[:] = [t for t in window if now - t < 60]
        if len(window) >= 100:
            return False
        window.append(now)
        return True

    def _record_failure(self, source_ip: str):
        self._failed_attempts[source_ip] += 1
        if self._failed_attempts[source_ip] >= 5:
            self._lockout_until[source_ip] = time.time() + 300

    def authenticate(self, token_id: str, api_key: str, source_ip: str) -> AuthResult:
        """Authenticate a request using token_id and api_key."""
        if not self._check_rate_limit(source_ip):
            return AuthResult(False, error="rate_limited")

        with self._lock:
            record = self._tokens.get(token_id)

        if record is None:
            self._record_failure(source_ip)
            return AuthResult(False, error="invalid_token")

        if record.revoked:
            self._record_failure(source_ip)
            return AuthResult(False, error="token_revoked")

        if self._is_token_expired(record):
            self._record_failure(source_ip)
            return AuthResult(False, error="token_expired")

        # Verify the API key
        derived = hashlib.pbkdf2_hmac(
            'sha256', api_key.encode('utf-8'), record.salt, 150000
        )

        if not hmac.compare_digest(derived, record.api_key_hash):
            self._record_failure(source_ip)
            return AuthResult(False, error="invalid_credentials")

        # Reset failure count on success
        self._failed_attempts[source_ip] = 0
        return AuthResult(True, tenant_id=record.tenant_id)


class MultiTenantGateway:
    """API Gateway with tenant isolation and authentication."""

    def __init__(self):
        self._token_store = SecureTokenStore()
        self._tenant_data: Dict[str, Dict] = {}
        self._audit_log: list = []
        self._lock = threading.Lock()

    def provision_tenant(self, tenant_id: str, api_key: str, ttl: int = 86400) -> str:
        """Provision a new tenant and return their token_id."""
        token_id = self._token_store.register_token(tenant_id, api_key, ttl)
        with self._lock:
            self._tenant_data[tenant_id] = {"created": time.time(), "active": True}
        return token_id

    def handle_request(self, token_id: str, api_key: str, 
                       source_ip: str, action: str, payload: dict) -> dict:
        """Handle an authenticated API request."""
        auth = self._token_store.authenticate(token_id, api_key, source_ip)

        if not auth.authenticated:
            self._log_audit("auth_failure", source_ip, None, auth.error)
            return {"status": "error", "code": 401, "message": auth.error}

        self._log_audit("request", source_ip, auth.tenant_id, action)

        # Process tenant-scoped action
        return self._process_action(auth.tenant_id, action, payload)

    def _process_action(self, tenant_id: str, action: str, payload: dict) -> dict:
        """Process an action within tenant scope."""
        allowed_actions = {"read", "write", "list", "delete"}
        if action not in allowed_actions:
            return {"status": "error", "code": 403, "message": "action_not_allowed"}

        with self._lock:
            tenant = self._tenant_data.get(tenant_id)
            if not tenant or not tenant.get("active"):
                return {"status": "error", "code": 403, "message": "tenant_inactive"}

        return {"status": "ok", "tenant_id": tenant_id, "action": action}

    def _log_audit(self, event_type: str, source_ip: str, 
                   tenant_id: Optional[str], detail: str):
        with self._lock:
            self._audit_log.append({
                "time": time.time(),
                "event": event_type,
                "ip": source_ip,
                "tenant": tenant_id,
                "detail": detail
            })
            # Keep bounded
            if len(self._audit_log) > 10000:
                self._audit_log = self._audit_log[-5000:]
